using System.CommandLine;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using Vericairn.Protocol;
using Vericairn.Records.Estate;
using Vericairn.Records.Model;
using Vericairn.Records.Types;

namespace Vericairn.Cli;

/// <summary>
/// A release's documentation set: the release notes generated from an estate's records, and the check that refuses a set missing
/// a document or a heading its manifest lists. The references themselves are generated by the product's own build tooling from
/// the build they document (for Vericairn, tools/Vericairn.DocsTool). One set per release, written once and frozen.
/// </summary>
internal static partial class Docs
{
    /// <summary>The manifest format a set declares.</summary>
    public const string ManifestFormat = "vericairn.docs/1";

    /// <summary>The manifest key of the window a set's notes cover: <c>{from, to}</c>, the records dated after from and up to to.</summary>
    private const string NotesWindow = "notes";

    private static readonly JsonSerializerOptions Indented = new() { WriteIndented = true };

    /// <summary>Where a set's notes begin, and how the notes say it.</summary>
    private sealed record Beginning(string At, string Says);

    /// <summary>
    /// Writes release notes from the estate's records since the previous set's notes ended, so that no record falls between two
    /// sets, and records their window in the set's manifest. The previous set is the directory the earlier version names beside the
    /// output; one that records no window (0.5.2 and earlier) gives the end its notes state; a time named with --since overrides
    /// both; and with no previous set the notes begin at the earlier publication.
    /// </summary>
    public static int Notes(string root, string fromVersion, string toVersion, string output, string? since, bool json)
    {
        try
        {
            if (since is not null && !RecordParser.IsTimestamp(since))
            {
                return Commands.Fail($"--since takes a record time such as 2026-10-15T12:06:00Z, not '{since}'.");
            }

            // The clock is read before the records: a record of the second the notes are made in can still be written after they read
            // the estate, so until the version's publication is recorded they end at the second before, and that record opens the next set.
            DateTimeOffset reading = DateTimeOffset.UtcNow;
            EstateModel model = Commands.LoadCopy(root);
            RecordEnvelope? from = Published(model, fromVersion);
            RecordEnvelope? to = Published(model, toVersion);
            if (from is null)
            {
                return Commands.Fail($"No published release record for {fromVersion} in this estate.");
            }

            if (Begin(model, from, fromVersion, output, since, out string? problem) is not Beginning beginning)
            {
                return Commands.Fail(problem!);
            }

            string manifestPath = Path.Combine(output, "manifest.json");
            JsonObject manifest = !File.Exists(manifestPath)
                ? new JsonObject { ["format"] = ManifestFormat, ["version"] = toVersion }
                : JsonNode.Parse(File.ReadAllText(manifestPath)) as JsonObject ?? throw new InvalidOperationException($"{manifestPath} is not a JSON object; the window of the notes is recorded in it.");
            string upper = to?.At ?? RecordParser.FormatTimestamp(reading.AddSeconds(-1));
            IReadOnlyList<RecordEnvelope> window = ReleaseContents.Window(model, beginning.At, upper);
            Directory.CreateDirectory(output);
            Write(output, "release-notes.md", ReleaseNotes(model, fromVersion, beginning, to, toVersion, window, upper));
            manifest[NotesWindow] = new JsonObject { ["from"] = beginning.At, ["to"] = upper };
            Write(output, "manifest.json", manifest.ToJsonString(Indented));
            if (json)
            {
                Console.Out.WriteLine(JsonSerializer.Serialize(new { output, from = fromVersion, to = toVersion, records = window.Count, published = to is not null, window = new { from = beginning.At, to = upper } }));
            }
            else
            {
                Console.Out.WriteLine($"{output}/release-notes.md: {window.Count} records between {fromVersion} and {(to is null ? $"now ({toVersion} not yet published)" : toVersion)}, {beginning.Says}; the window, after {beginning.At} up to {upper}, is recorded in {manifestPath}");
            }

            return Commands.Clean;
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or InvalidOperationException or JsonException)
        {
            return Commands.Fail(exception.Message);
        }
    }

    /// <summary>
    /// Where the notes begin: the time --since names; else where the previous set's notes ended, as its manifest records it or, for a
    /// set made before the window was recorded, as its notes state it (to the minute, or to the second when they end at a publication
    /// this estate records); else, when no previous set is found beside this one, the earlier version's publication.
    /// </summary>
    private static Beginning? Begin(EstateModel model, RecordEnvelope from, string fromVersion, string output, string? since, out string? problem)
    {
        problem = null;
        if (since is not null)
        {
            return new Beginning(since, $"since {When(since)} (the time named when they were generated)");
        }

        string previous = Path.Combine(Path.GetDirectoryName(Path.TrimEndingDirectorySeparator(Path.GetFullPath(output))) ?? string.Empty, fromVersion);
        string manifestPath = Path.Combine(previous, "manifest.json");
        if (File.Exists(manifestPath) && JsonNode.Parse(File.ReadAllText(manifestPath)) is JsonObject manifest && manifest[NotesWindow] is JsonNode recorded)
        {
            string? end = recorded is JsonObject window && window["to"] is JsonValue value && value.TryGetValue(out string? text) ? text : null;
            if (end is null || !RecordParser.IsTimestamp(end))
            {
                problem = $"{manifestPath} records the window of its notes without a valid end; name where these notes begin with --since <time>.";
                return null;
            }

            return new Beginning(end, $"since the end of the notes of {fromVersion} ({When(end)})");
        }

        string notes = Path.Combine(previous, "release-notes.md");
        if (!File.Exists(notes))
        {
            return new Beginning(from.At, $"since the publication of {fromVersion} ({When(from.At)}; no documentation set of {fromVersion} beside this one says where its notes ended)");
        }

        string overview = File.ReadAllText(notes).ReplaceLineEndings("\n");
        int sections = overview.IndexOf("\n## ", StringComparison.Ordinal);
        Match stated = StatedEnd().Match(sections < 0 ? overview : overview[..sections]);
        if (!stated.Success)
        {
            problem = $"{notes} records no window and states no end that can be read; name where these notes begin with --since <time>.";
            return null;
        }

        // A set that ends at a publication ends at that record, to the second, where the estate holds it; otherwise at its minute.
        string minute = stated.Groups["end"].Value.Replace(' ', 'T') + ":00Z";
        string? version = stated.Groups["version"].Success ? stated.Groups["version"].Value : null;
        if (version is not null && Published(model, version) is RecordEnvelope publication && publication.At.StartsWith(minute[..16], StringComparison.Ordinal))
        {
            return new Beginning(publication.At, $"since the end of the notes of {fromVersion} (the publication of {version}, {When(publication.At)})");
        }

        return new Beginning(minute, $"since {When(minute)} (where the notes of {fromVersion} end, as they state it to the minute, so a record of that minute may be in both)");
    }

    /// <summary>
    /// Refuses a set that lacks a document its manifest or the product's declaration requires, or a heading for a command, an
    /// operation or a record type its manifest lists, naming every gap at once. Whether the manifest matches a build is the
    /// product's own build tooling's question, asked where that build is (the release workflow asks it before any draft).
    /// </summary>
    public static int Check(string directory, string? declaration, bool json)
    {
        var findings = new List<FindingDto>();
        if (!Directory.Exists(directory))
        {
            return Commands.Fail($"{directory}: no such directory.");
        }

        string manifestPath = Path.Combine(directory, "manifest.json");
        JsonElement manifest = default;
        bool haveManifest = false;
        if (!File.Exists(manifestPath))
        {
            findings.Add(new FindingDto("error", "docs.manifest", "manifest.json", "Missing; the product's build tooling writes it with the references."));
        }
        else
        {
            try
            {
                using JsonDocument document = JsonDocument.Parse(File.ReadAllBytes(manifestPath));
                manifest = document.RootElement.Clone();
                haveManifest = true;
                if (Str(manifest, "format") != ManifestFormat)
                {
                    findings.Add(new FindingDto("error", "docs.manifest", "manifest.json", $"Format '{Str(manifest, "format")}' is not {ManifestFormat}."));
                }
            }
            catch (JsonException exception)
            {
                findings.Add(new FindingDto("error", "docs.manifest", "manifest.json", "Not valid JSON: " + exception.Message));
            }
        }

        var required = new SortedSet<string>(haveManifest ? Strings(manifest, "documents") : [], StringComparer.Ordinal);
        if (declaration is not null)
        {
            try
            {
                using JsonDocument declared = JsonDocument.Parse(File.ReadAllBytes(declaration));
                foreach (JsonElement name in declared.RootElement.EnumerateArray().Where(n => n.ValueKind == JsonValueKind.String))
                {
                    if (haveManifest && !required.Contains(name.GetString()!))
                    {
                        findings.Add(new FindingDto("error", "docs.declaration", "manifest.json", $"The product declares {name.GetString()} as a document of every set; the manifest does not list it."));
                    }

                    required.Add(name.GetString()!);
                }
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException or JsonException or InvalidOperationException)
            {
                return Commands.Fail($"{declaration}: not a readable JSON array of document names: {exception.Message}");
            }
        }

        if (haveManifest && required.Count == 0)
        {
            findings.Add(new FindingDto("error", "docs.manifest", "manifest.json", "Names no documents; the set's manifest lists the documents every set of the product holds."));
        }

        foreach (string name in required)
        {
            string path = Path.Combine(directory, name);
            if (!File.Exists(path) || new FileInfo(path).Length == 0)
            {
                findings.Add(new FindingDto("error", "docs.document", name, "Missing or empty; every set holds this document."));
            }
        }

        if (haveManifest)
        {
            string version = Str(manifest, "version") ?? string.Empty;
            Covered(directory, "cli-reference.md", Strings(manifest, "commands"), c => $"`vericairn {c}`", "docs.command", findings);
            Covered(directory, "api-reference.md", Strings(manifest, "operations"), o => $"`{o}`", "docs.operation", findings);
            Covered(directory, "record-reference.md", Strings(manifest, "recordTypes"), t => $"`{t}`", "docs.record-type", findings);
            string readme = Path.Combine(directory, "README.md");
            if (File.Exists(readme) && !File.ReadAllText(readme).Contains(version, StringComparison.Ordinal))
            {
                findings.Add(new FindingDto("error", "docs.version", "README.md", $"Does not name the version {version} the set documents."));
            }
        }

        int errors = findings.Count(f => f.Severity == "error");
        return Commands.ReportFindings(new FindingsResponse(errors == 0 ? $"{directory}: complete" : $"{directory}: incomplete", errors, 0, findings), json);
    }

    private static void Covered(string directory, string file, List<string> expected, Func<string, string> heading, string code, List<FindingDto> findings)
    {
        string path = Path.Combine(directory, file);
        if (!File.Exists(path))
        {
            return;
        }

        HashSet<string> headings = File.ReadLines(path).Where(l => l.StartsWith('#')).ToHashSet(StringComparer.Ordinal);
        foreach (string item in expected)
        {
            string wanted = heading(item);
            if (!headings.Any(h => h.Contains(wanted, StringComparison.Ordinal)))
            {
                findings.Add(new FindingDto("error", code, file, $"No heading for {wanted}."));
            }
        }
    }

    private static RecordEnvelope? Published(EstateModel model, string version) =>
        model.Current("release").FirstOrDefault(r => Str(r.Body, "version") == version && Str(r.Body, "status") == "published");

    private static string ReleaseNotes(EstateModel model, string fromVersion, Beginning beginning, RecordEnvelope? to, string toVersion, IReadOnlyList<RecordEnvelope> window, string upper)
    {
        var lines = new List<string>
        {
            $"# Release notes, Vericairn {toVersion}",
            string.Empty,
            to is null
                ? $"Prepared by `vericairn docs notes` before the release build, from the estate's records {beginning.Says} up to {When(upper)}; the records are the source and this page is a rendering. The publication of {toVersion} is not yet recorded: its commit, workflow run, artifacts by hash and qualified platforms are in the release record the estate writes when the draft is observed and, once published, in the published revision; `limitations-and-platforms.md` of this set states what was known before the build."
                : $"Generated by `vericairn docs notes` from the estate's records {beginning.Says} up to the publication of {toVersion} ({When(to.At)}); the records are the source and this page is a rendering. Release {toVersion} was built from commit {Str(to.Body, "commit")}; signing: {Str(to.Body, "signing")}; qualified platforms: {string.Join(", ", Strings(to.Body, "qualified"))}.",
            string.Empty,
            "## What the release contains",
            string.Empty,
        };
        if (to is null)
        {
            lines.Add($"The release record of {toVersion} is written when its draft is observed; until then the accepted work below is what the release contains.");
        }
        else if (to.Body.TryGetProperty("evidence", out JsonElement evidence))
        {
            lines.AddRange(evidence.EnumerateArray().Select(e => "- " + Str(e, "summary")));
        }

        if (to is not null && to.Body.TryGetProperty("recordFormat", out JsonElement format))
        {
            string reads = format.TryGetProperty("reads", out JsonElement readsElement) && readsElement.ValueKind == JsonValueKind.Array ? string.Join(", ", readsElement.EnumerateArray().Select(r => r.ToString())) : string.Empty;
            string writes = format.TryGetProperty("writes", out JsonElement writesElement) ? writesElement.ToString() : string.Empty;
            lines.Add($"- Record format: reads {reads}, writes {writes}.");
        }

        // A result is listed as accepted only when an acceptance of its exact revision is on record; any other result of the
        // period is a claim to inspect, never part of what the release is known to contain. The progress report reads the same.
        (IReadOnlyList<ReleaseContents.Accepted> acceptedResults, IReadOnlyList<RecordEnvelope> openResults) = ReleaseContents.Results(model, window);
        lines.Add(string.Empty);
        lines.Add("## Work accepted");
        lines.Add(string.Empty);
        if (acceptedResults.Count == 0)
        {
            lines.Add("None in this window.");
            lines.Add(string.Empty);
        }

        foreach (ReleaseContents.Accepted result in acceptedResults)
        {
            Result(lines, result.Result, result.Order);
        }

        if (openResults.Count > 0)
        {
            lines.Add("## Work recorded, not yet accepted");
            lines.Add(string.Empty);
            lines.Add("Results of this period with no acceptance of their exact revision: claims to inspect, not part of what the release is known to contain.");
            lines.Add(string.Empty);
            foreach (RecordEnvelope result in openResults)
            {
                Result(lines, result, ReleaseContents.OrderOf(model, result));
            }
        }

        Section(lines, "Decisions", window.Where(r => r.Type == "decision").Select(r => $"**{Str(r.Body, "title")}** ({When(r.At)}, decision {r.Id}): {Str(r.Body, "summary")}"));
        Section(lines, "Work orders opened or revised", window.Where(r => r.Type == "work-order").Select(r => $"**{Str(r.Body, "key")}** ({Str(r.Body, "kind")}): {Str(r.Body, "title")}{(r.Supersedes is null ? string.Empty : " (revised)")}."));
        Section(lines, "Milestone and release acceptances", window.Where(r => r.Type == "acceptance" && !(r.Body.TryGetProperty("self", out JsonElement self) && self.ValueKind == JsonValueKind.True)).Select(r =>
        {
            RecordEnvelope? subject = r.Subject is null ? null : model.ById.GetValueOrDefault(r.Subject.Id);
            string what = subject is null ? r.Subject?.ToString() ?? string.Empty : subject.Type == "release" ? "release " + Str(subject.Body, "version") : Str(subject.Body, "key") ?? subject.Id;
            return $"{what}: \"{Str(r.Body, "statement")}\" (acceptance {r.Id}, {When(r.At)}{(r.HasSignatures ? ", signed" : string.Empty)})";
        }));
        Section(lines, "Identity and policy", window.Where(r => r.Type is "device" or "admission" or "principal" or "estate").Select(r => r.Type switch
        {
            "device" => $"Device \"{Str(r.Body, "name")}\" recorded ({r.Id}).",
            "admission" => $"Device admitted to author records, scope {Str(r.Body, "scope")} ({r.Id}).",
            "principal" => $"Principal {(r.Supersedes is null ? "recorded" : "revised")}: \"{Str(r.Body, "name")}\" ({r.Id}).",
            _ => $"Charter revised ({r.Id}).",
        }));
        Section(lines, "Design documents revised", window.Where(r => r.Type == "document-revision").Select(r => $"{Str(r.Body, "title")} revision {Str(r.Body, "revision") ?? Num(r.Body, "revision")} (`{Str(r.Body, "path")}`): {Str(r.Body, "summary")}"));
        // The window begins where the previous notes ended, so it also holds the previous release's own candidate and publication.
        Section(lines, "The release itself", window.Where(r => r.Type == "release" && Str(r.Body, "version") == toVersion).Select(ReleaseLine));
        List<string> others = window.Where(r => r.Type == "release" && Str(r.Body, "version") != toVersion).Select(ReleaseLine).ToList();
        if (others.Count > 0)
        {
            Section(lines, "Other releases recorded in this window", others);
        }

        Section(lines, "Upgrading", window.Where(r => r.Type == "migration").Select(r => $"Migration {r.Id}: from {Str(r.Body, "fromPin")} to {Str(r.Body, "toPin")}, record format {Num(r.Body, "fromFormat")} to {Num(r.Body, "toFormat")}; migrations applied: {(Strings(r.Body, "migrations") is { Count: > 0 } m ? string.Join(", ", m) : "none")}; changes: {string.Join("; ", Strings(r.Body, "changes"))}."));
        lines.Add($"An estate on {fromVersion} upgrades with `vericairn estate upgrade --to {toVersion} --by <principal>` run with the {toVersion} binary once the published release record is in the estate; `--check` shows the plan first.");
        return string.Join("\n", lines);
    }

    private static string ReleaseLine(RecordEnvelope r) =>
        $"{Str(r.Body, "version")} {Str(r.Body, "status")} ({r.Id}, {When(r.At)}); signing: {Str(r.Body, "signing")}; qualified: {string.Join(", ", Strings(r.Body, "qualified"))}.";

    private static void Section(List<string> lines, string title, IEnumerable<string> items)
    {
        List<string> list = items.ToList();
        lines.Add("## " + title);
        lines.Add(string.Empty);
        if (list.Count == 0)
        {
            lines.Add("None in this window.");
        }
        else
        {
            lines.AddRange(list.Select(i => "- " + i));
        }

        lines.Add(string.Empty);
    }

    private static void Result(List<string> lines, RecordEnvelope result, RecordEnvelope? order)
    {
        lines.Add("### " + (order is null ? "Result " + result.Id : Str(order.Body, "key") + ": " + Str(order.Body, "title")));
        lines.Add(string.Empty);
        lines.Add($"Result {result.Id} ({Str(result.Body, "outcome")}), recorded {When(result.At)}. {Str(result.Body, "summary")}");
        List<string> limitations = Strings(result.Body, "limitations");
        if (limitations.Count > 0)
        {
            lines.Add(string.Empty);
            lines.Add("Limitations recorded:");
            lines.AddRange(limitations.Select(l => "- " + l));
        }

        lines.Add(string.Empty);
    }

    private static string When(string at) => at.Length >= 16 ? at[..10] + " " + at[11..16] + " UTC" : at;

    private static string? Str(JsonElement element, string name) =>
        element.ValueKind == JsonValueKind.Object && element.TryGetProperty(name, out JsonElement value) && value.ValueKind == JsonValueKind.String ? value.GetString() : null;

    private static string Num(JsonElement element, string name) =>
        element.ValueKind == JsonValueKind.Object && element.TryGetProperty(name, out JsonElement value) && value.ValueKind == JsonValueKind.Number ? value.ToString() : string.Empty;

    private static List<string> Strings(JsonElement element, string name) =>
        element.ValueKind == JsonValueKind.Object && element.TryGetProperty(name, out JsonElement value) && value.ValueKind == JsonValueKind.Array
            ? value.EnumerateArray().Where(v => v.ValueKind == JsonValueKind.String).Select(v => v.GetString()!).ToList()
            : [];

    private static void Write(string directory, string name, string text) => File.WriteAllText(Path.Combine(directory, name), text.EndsWith('\n') ? text : text + "\n");

    /// <summary>
    /// The end a set's notes state in their overview, as `vericairn docs notes` writes it: "up to &lt;minute&gt; UTC" before the
    /// build, or "and (or up to) the publication of &lt;version&gt; (&lt;minute&gt; UTC)" after it.
    /// </summary>
    [GeneratedRegex(@"(?:up to|and) (?:the publication of (?<version>[^ ()]+) \()?(?<end>\d{4}-\d{2}-\d{2} \d{2}:\d{2}) UTC\)?; the records are the source")]
    private static partial Regex StatedEnd();
}
